  it("single key yields a one-entry (or empty) change list", () => {
    const doc = parseScoreDoc(XML);
    expect(doc.keyChanges).toEqual([{ measure: 1, fifths: -1, mode: null }]);
  });

  it("parses pitch, type, dots and measure numbers", () => {
    const n1 = doc.notes.find((n) => n.exportId === "hs-sn-000001");
    expect(n1?.step).toBe("C");
    expect(n1?.octave).toBe(4);
    expect(n1?.type).toBe("quarter");
    expect(n1?.dots).toBe(0);
    expect(n1?.measure).toBe(1);
    const n2 = doc.notes.find((n) => n.exportId === "hs-sn-000002");
    expect(n2?.alter).toBe(-1);
    expect(n2?.dots).toBe(1);
  });

  it("marks rests and tie membership", () => {
    const rest = doc.notes.find((n) => n.exportId === "hs-rest-000001");
    expect(rest?.isRest).toBe(true);
    expect(rest?.canonicalId).toBeNull();
    const t1 = doc.notes.find((n) => n.exportId === "hs-sn-000003");
    const t2 = doc.notes.find((n) => n.exportId === "hs-sn-000003-2");
    expect(t1?.tied).toBe(true);
    expect(t2?.tied).toBe(true);
    expect(t2?.measure).toBe(2);
  });

  it("groups tie fragments under one canonical id", () => {
    const map = notesByCanonical(doc);
    expect(map.get("sn-000003")?.map((n) => n.exportId)).toEqual([
      "hs-sn-000003",
      "hs-sn-000003-2",
    ]);
    const byExport = notesByExportId(doc);
    expect(byExport.get("hs-rest-000001")?.isRest).toBe(true);
  });

  it("throws on malformed XML", () => {
    expect(() => parseScoreDoc("<score-partwise><part")).toThrow();
  });
});

describe("labels", () => {
  const doc = parseScoreDoc(XML);
  const n1 = doc.notes.find((n) => n.exportId === "hs-sn-000001")!;
  const n2 = doc.notes.find((n) => n.exportId === "hs-sn-000002")!;
  const rest = doc.notes.find((n) => n.exportId === "hs-rest-000001")!;

  it("formats Japanese pitch labels", () => {
    expect(pitchLabel(n1)).toBe("C4");
    expect(pitchLabel(n2)).toBe("B♭3");
    expect(pitchLabel(rest)).toBe("");
  });

  it("formats Japanese duration labels", () => {
    expect(noteTypeJa(n1)).toBe("四分音符");
    expect(noteTypeJa(n2)).toBe("付点四分音符");
    expect(noteTypeJa(rest)).toBe("付点四分休符");
  });

  it("describes a note for announcements", () => {
    expect(describeNote(n1)).toBe("第1小節 C4 四分音符");
    const t1 = doc.notes.find((n) => n.exportId === "hs-sn-000003")!;
    expect(describeNote(t1)).toContain("・タイ");
  });
});

/**
 * MusicXML → flat note/rest model used for the properties inspector and the
 * accessible score representation (GUI_UX_SPEC §24: a11y must not depend on
 * raw SVG alone). This is a presentation helper only — canonical identity
 * still comes from `hs-sn-*` ids, not from parse order.
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlRestId } from "./ids";

/** MusicXML <mode> values the engine emits (domain/score.py KeySignature). */
export type KeyMode = "major" | "minor";

/** Parse a MusicXML <mode> text into the domain mode; anything
 *  unrecognized (dorian, none, ...) maps to null so callers keep the
 *  major default rather than trusting a free-form string. */
export function parseKeyMode(text: string | null | undefined): KeyMode | null {
  if (text === "major" || text === "minor") return text;
  return null;
}

export interface ParsedNote {
  exportId: string; // MusicXML note/@id, e.g. hs-sn-000003-2 / hs-rest-000001
  canonicalId: string | null; // sn-000003, or null for rests
  isRest: boolean;
  chord: boolean;
  measure: number;
  step?: string;
  alter?: number;
  octave?: number;
  type?: string;
  dots: number;
  /** This note is a member of a tie chain (start/stop). */
  tied: boolean;
}

export interface ScoreDoc {
  title: string;
  notes: ParsedNote[];
  measureCount: number;
  /** `<sound tempo>` beats per minute, when present. */
  tempoBpm: number | null;
  /** Time signature like "4/4", when present. */
  meter: string | null;
  /** Key signature fifths (−7…+7), when present. */
 keyFifths: number | null;
  /** #252: key mode (major/minor) when the document declares one; null
   *  keeps the major default for legacy MusicXML without <mode>. */
  keyMode: KeyMode | null;
  /** #146: key changes with their measure numbers, head first. Empty
   *  or single-entry = the piece stays in keyFifths. */
  keyChanges: { measure: number; fifths: number; mode: KeyMode | null }[];
  /** #134: a <sound><swing> direction exists — the piece is marked
   *  as swung (straight eighths play in the detected ratio). */
  swingFeel: boolean;
}

const TYPE_JA: Record<string, string> = {
  whole: "全",
  half: "二分",
  quarter: "四分",
  eighth: "八分",
  "16th": "十六分",
  "32nd": "三十二分",
  "64th": "六十四分",
};

export function noteTypeJa(note: ParsedNote): string {
  const base = TYPE_JA[note.type ?? ""] ?? (note.type ?? "");
  const dotted = note.dots > 0 ? "付点" : "";
  const unit = note.isRest ? "休符" : "音符";
  return `${dotted}${base}${unit}`.replace(/^付点$/, "");
}

export function pitchLabel(note: ParsedNote): string {
  if (note.isRest || note.step === undefined || note.octave === undefined) return "";
  const acc =
    note.alter === undefined || note.alter === 0
      ? ""
      : note.alter > 0
        ? "♯".repeat(note.alter)
        : "♭".repeat(-note.alter);
  return `${note.step}${acc}${note.octave}`;
}

/** e.g. "第3小節 B♭3 付点四分音符 (sn-000003)" / "第2小節 四分休符" */
export function describeNote(note: ParsedNote): string {
  const where = `第${note.measure}小節`;
  if (note.isRest) return `${where} ${noteTypeJa(note)}`;
  const pitch = pitchLabel(note);
  const tie = note.tied ? "・タイ" : "";
  return `${where} ${pitch} ${noteTypeJa(note)}${tie}`;
}

export function parseScoreDoc(xml: string): ScoreDoc {
  const doc = new DOMParser().parseFromString(xml, "application/xml");
  if (doc.querySelector("parsererror")) {
    throw new Error("MusicXML parse failed");
  }
  const title =
    doc.querySelector("movement-title")?.textContent?.trim() ||
    doc.querySelector("work-title")?.textContent?.trim() ||
    "";
  const tempoText = doc.querySelector("sound[tempo]")?.getAttribute("tempo");
  const tempoBpm =
    tempoText != null && Number.isFinite(Number(tempoText)) ? Number(tempoText) : null;
  const beats = doc.querySelector("time > beats")?.textContent?.trim();
  const beatType = doc.querySelector("time > beat-type")?.textContent?.trim();
  const meter = beats && beatType ? `${beats}/${beatType}` : null;
  const fifthsText = doc.querySelector("key > fifths")?.textContent;
 const keyFifths =
   fifthsText != null && Number.isFinite(Number(fifthsText)) ? Number(fifthsText) : null;
  const keyMode = parseKeyMode(
    doc.querySelector("key > mode")?.textContent?.trim(),
  );
  // #134: the engine emits <sound><swing> on swing-detected scores.
  const swingFeel = doc.querySelector("sound > swing") !== null;

  const notes: ParsedNote[] = [];
  let measureCount = 0;
  const keyChanges: { measure: number; fifths: number; mode: KeyMode | null }[] = [];
  const parts = Array.from(doc.querySelectorAll("part"));
  for (const measure of Array.from(
    parts[0]?.querySelectorAll(":scope > measure") ?? [],
  )) {
    const number = Number(measure.getAttribute("number") ?? measureCount + 1);
    // Mid-piece key changes (#133): every <key> under attributes —
    // a measure can carry more than one (offset insertions share the
    // element), so collect them all.
    for (const keyEl of Array.from(
      measure.querySelectorAll(":scope > attributes > key"),
    )) {
     const f = keyEl.querySelector("fifths")?.textContent;
     if (f != null && Number.isFinite(Number(f))) {
        keyChanges.push({
          measure: number,
          fifths: Number(f),
          mode: parseKeyMode(keyEl.querySelector("mode")?.textContent?.trim()),
        });
     }
    }
  }
  for (const measure of Array.from(doc.querySelectorAll("part > measure"))) {
    const number = Number(measure.getAttribute("number") ?? measureCount + 1);
    measureCount = Math.max(measureCount, Number.isFinite(number) ? number : measureCount + 1);
    for (const noteEl of Array.from(measure.querySelectorAll(":scope > note"))) {
      const exportId = noteEl.getAttribute("id") ?? "";
      const isRest =
        noteEl.querySelector(":scope > rest") !== null || isMusicxmlRestId(exportId);
      const pitchEl = noteEl.querySelector(":scope > pitch");
      const alterText = pitchEl?.querySelector("alter")?.textContent;
      const tied =
        noteEl.querySelector('tie[type="start"], tie[type="stop"]') !== null ||
        noteEl.querySelector("notations > tied") !== null;
      notes.push({
        exportId,
        canonicalId: canonicalNoteIdFromMusicxml(exportId),
        isRest,
        chord: noteEl.querySelector(":scope > chord") !== null,
        measure: number,
        step: pitchEl?.querySelector("step")?.textContent ?? undefined,
        alter:
          alterText !== undefined && alterText !== null ? Number(alterText) : undefined,
        octave: pitchEl?.querySelector("octave")?.textContent
          ? Number(pitchEl.querySelector("octave")!.textContent)
          : undefined,
        type: noteEl.querySelector(":scope > type")?.textContent ?? undefined,
        dots: noteEl.querySelectorAll(":scope > dot").length,
        tied,
      });
    }
  }
  return { title, notes, measureCount, tempoBpm, meter, keyFifths, keyMode, keyChanges, swingFeel };
}

/** canonical id → parsed fragments (both tie fragments and chords land here). */
export function notesByCanonical(doc: ScoreDoc): Map<string, ParsedNote[]> {
  const map = new Map<string, ParsedNote[]>();
  for (const note of doc.notes) {
    if (!note.canonicalId) continue;
    const list = map.get(note.canonicalId) ?? [];
    list.push(note);
    map.set(note.canonicalId, list);
  }
  return map;
}

/** export id → parsed note (includes rests, keyed by their hs-rest-* id). */
export function notesByExportId(doc: ScoreDoc): Map<string, ParsedNote> {
  const map = new Map<string, ParsedNote>();
  for (const note of doc.notes) map.set(note.exportId, note);
  return map;
}

/**
 * XmlScoreDocument — `ScoreDocumentPort` over arbitrary MusicXML bodies
 * (ENG-002).
 *
 * The fixture adapter proved the contract; this is the general form the
 * real engine result slots into: the transcription job returns
 * `musicXmlConcert` + `musicXmlHornF` (same canonical `hs-sn-*` ids in
 * both — the export layer's contract), the `sr-*` revision id, and the
 * typed review issues. Review decisions and note edits live here, keyed
 * to `revisionId` — a new score revision constructs a fresh document,
 * so stale decisions are never carried across (domain/review.py rule).
 */
import type { PitchViewSetting } from "../commands/types";
import type { ScoreDocumentMeta, ScoreDocumentPort } from "./document";
import { parseScoreDoc } from "./scoreDoc";
import type { ReviewIssueStatus, ScoreReviewIssue } from "./review";
import {
  applyNoteEdits,
  isEmptyNoteEdit,
  type ScoreNoteEdit,
} from "./scoreEdits";

export interface XmlScoreDocumentSources {
  /** Canonical sounding-pitch MusicXML (`<sound tempo>` etc. drive meta). */
  readonly concertXml: string;
  /** Written-pitch F管 presentation of the SAME canonical notes. */
  readonly hornXml: string;
  /** `sr-*`/`rev-*` revision id the decisions/edits bind to. */
  readonly revisionId: string;
  /** Engine review issues for this revision (`[]` = honestly clean). */
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict — the base the engine's
   *  `score.edit` re-realizes from (undefined for fixture/dev). */
  readonly canonicalDocument?: unknown;
  /** #272: issues the engine detected but the surfacing cap omitted. */
  readonly omittedIssueCount?: number;
}

export class XmlScoreDocument implements ScoreDocumentPort {
  private _revisionId: string;
  private _meta: ScoreDocumentMeta;
  private concertXml: string;
  private hornXml: string;
  private canonicalDoc: unknown | null;
  private issues: readonly ScoreReviewIssue[];
  private _omittedIssueCount = 0;
  private decisions = new Map<string, ReviewIssueStatus>();
  /** #225: decisions/issues are revision-bound — a score.edit swap
   *  mints a new revision, so the old revision's set is stashed here
   *  and a swap back (undo) restores exactly that revision's state. */
  private readonly issuesByRevision = new Map<
    string,
    readonly ScoreReviewIssue[]
  >();
  private readonly decisionsByRevision = new Map<
    string,
    Map<string, ReviewIssueStatus>
  >();
  private readonly edits = new Map<string, ScoreNoteEdit>();
  private editCounter = 0;

  constructor(src: XmlScoreDocumentSources) {
    this._revisionId = src.revisionId;
    this.issues = src.issues;
    this.concertXml = src.concertXml;
    this.hornXml = src.hornXml;
    this.canonicalDoc = src.canonicalDocument ?? null;
    this._meta = XmlScoreDocument.computeMeta(src.concertXml);
    this._omittedIssueCount = src.omittedIssueCount ?? 0;
    this._meta = { ...this._meta, omittedIssueCount: this._omittedIssueCount };
  }

  private static computeMeta(xml: string): ScoreDocumentMeta {
    const doc = parseScoreDoc(xml);
    const canonical = new Set(
      doc.notes.map((n) => n.canonicalId).filter(Boolean),
    );
    return {
      title: doc.title,
      tempoBpm: doc.tempoBpm,
      meter: doc.meter,
     keyFifths: doc.keyFifths,
     keyChanges: doc.keyChanges,
      keyMode: doc.keyMode,
      swingFeel: doc.swingFeel,
      measureCount: doc.measureCount,
      noteCount: canonical.size,
      omittedIssueCount: 0,
    };
  }

  get revisionId(): string {
    return this._revisionId;
  }

  get meta(): ScoreDocumentMeta {
    return this._meta;
  }

  get editVersion(): number {
    return this.editCounter;
  }

  musicXml(view: PitchViewSetting): string {
    const base = view === "hornF" ? this.hornXml : this.concertXml;
    return applyNoteEdits(base, this.edits);
  }

  reviewIssues(): readonly ScoreReviewIssue[] {
    return this.issues.map((issue) => {
      const decided = this.decisions.get(issue.id);
      return decided !== undefined ? { ...issue, status: decided } : issue;
    });
  }

  recordReviewDecision(issueId: string, status: ReviewIssueStatus): void {
    this.decisions.set(issueId, status);
    this.editCounter += 1;
  }

  noteEdits(): ReadonlyMap<string, ScoreNoteEdit> {
    return this.edits;
  }

  setNoteEdit(canonicalId: string, edit: ScoreNoteEdit | null): void {
    if (edit == null || isEmptyNoteEdit(edit)) this.edits.delete(canonicalId);
    else this.edits.set(canonicalId, edit);
    this.editCounter += 1;
  }

  /* ---- #115: engine rhythm edits swap content in place ---- */

  canonicalDocument(): unknown | null {
    return this.canonicalDoc;
  }

  contentSnapshot() {
    return {
      concertXml: this.concertXml,
      hornXml: this.hornXml,
      revisionId: this._revisionId,
      canonicalDocument: this.canonicalDoc,
    };
  }

  /** Swap XML bodies + revision + canonical payload in place. Meta is
   *  recomputed from the new concert XML (measure/note counts can move).
   *  Note edits and review decisions survive — canonical ids are stable,
   *  and the session's undo stack keeps working across the swap. */
  replaceContent(next: {
    concertXml: string;
    hornXml: string;
    revisionId: string;
    canonicalDocument: unknown;
  }): void {
    if (next.revisionId !== this._revisionId) {
      // #225: stash the outgoing revision's issue set + decisions, then
      // restore the incoming revision's own set (empty for a revision
      // never seen — a score.edit result carries no issue list).
      this.issuesByRevision.set(this._revisionId, this.issues);
      this.decisionsByRevision.set(this._revisionId, this.decisions);
      this.issues = this.issuesByRevision.get(next.revisionId) ?? [];
      this.decisions =
        this.decisionsByRevision.get(next.revisionId) ?? new Map();
    }
    this.concertXml = next.concertXml;
    this.hornXml = next.hornXml;
    this._revisionId = next.revisionId;
    this.canonicalDoc = next.canonicalDocument;
    this._meta = XmlScoreDocument.computeMeta(next.concertXml);
    this._meta = { ...this._meta, omittedIssueCount: this._omittedIssueCount };
    this.editCounter += 1;
  }
}

/** Fields extracted from a completed transcription job's `result`. */
export interface EngineScoreDocumentInput {
  readonly concertXml: string;
  readonly hornXml: string;
  readonly revisionId: string;
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict from the job result. */
  readonly canonicalDocument?: unknown;
  /** #272: issues the engine detected but the surfacing cap omitted. */
  readonly omittedIssueCount?: number;
}

/**
 * Build the score document for a real transcription result. Returns
 * `null` when the payload is not usable (missing/invalid MusicXML) so
 * the caller can fall back honestly instead of mounting a broken score.
 */
export function createEngineScoreDocument(
  input: EngineScoreDocumentInput,
): ScoreDocumentPort | null {
  if (!input.concertXml || !input.hornXml) return null;
  try {
    return new XmlScoreDocument({
      concertXml: input.concertXml,
      hornXml: input.hornXml,
      revisionId: input.revisionId,
      issues: input.issues,
      canonicalDocument: input.canonicalDocument,
      omittedIssueCount: input.omittedIssueCount,
    });
  } catch {
    // parseScoreDoc throws on malformed MusicXML — a corrupt engine
    // payload must not take down the workspace.
    return null;
  }
}

/**
 * Extract the document input from `session.lastResult` (the completed
 * job's `result` payload). Returns `null` when the result carries no
 * MusicXML — e.g. the mock port's stand-in result — so callers fall
 * back to the fixture document in dev sessions.
 */
export function engineDocumentFromResult(
  result: unknown,
): EngineScoreDocumentInput | null {
  if (typeof result !== "object" || result === null) return null;
  const r = result as Record<string, unknown>;
  const concert = r.musicXmlConcert;
  const horn = r.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") return null;
  return {
    concertXml: concert,
    hornXml: horn,
    revisionId:
      typeof r.scoreRevision === "string" ? r.scoreRevision : "rev-engine",
    issues: [],
    canonicalDocument:
      typeof r.scoreDocument === "object" && r.scoreDocument !== null
        ? r.scoreDocument
        : undefined,
    // #272: meta.reviewSummary.omitted — the cap never truncates
    // silently; the review bar shows how many were left out.
    omittedIssueCount: (() => {
      const meta = r.meta as Record<string, unknown> | undefined;
      const summary = meta?.reviewSummary as
        Record<string, unknown> | undefined;
      const n = summary?.omitted;
      return typeof n === "number" && n > 0 ? n : 0;
    })(),
  };
}
